import { spawn } from 'child_process';
import net from 'net';
import fs from 'fs';
import http from 'http';

// Termux sets the PREFIX env var — use it for dynamic path resolution
const TERMUX_PREFIX =
  process.env.PREFIX ||
  '/data/data/com.termux/files/usr';

const TERMUX_CHROME_PATHS = [
  `${TERMUX_PREFIX}/bin/chromium-browser`,
  `${TERMUX_PREFIX}/bin/chromium`,
  // Fallback hardcoded paths in case PREFIX differs
  '/data/data/com.termux/files/usr/bin/chromium-browser',
  '/data/data/com.termux/files/usr/bin/chromium',
];

/**
 * Detect if running inside a Termux environment.
 */
export function isTermux() {
  return (
    process.env.TERMUX_VERSION !== undefined ||
    (typeof process.env.PREFIX === 'string' &&
      process.env.PREFIX.includes('com.termux')) ||
    fs.existsSync('/data/data/com.termux')
  );
}

/**
 * Return the path to the first available Chromium binary in Termux.
 * Returns null if none found.
 */
export function getTermuxChromePath() {
  const seen = new Set();
  for (const p of TERMUX_CHROME_PATHS) {
    if (seen.has(p)) continue;
    seen.add(p);
    try {
      if (fs.existsSync(p)) return p;
    } catch (_) {}
  }
  return null;
}

/**
 * Chrome/Chromium flags that are essential on Termux.
 * These must always be present regardless of ignoreAllFlags.
 */
export function getTermuxFlags() {
  return [
    '--no-sandbox',
    '--disable-setuid-sandbox',
    '--disable-dev-shm-usage',
    '--disable-gpu',
    '--no-first-run',
    '--no-zygote',
  ];
}

/**
 * Merge Termux essential flags into an existing flags array,
 * skipping duplicates.
 */
export function mergeTermuxFlags(chromeFlags) {
  const essential = getTermuxFlags();
  const merged = [...chromeFlags];
  for (const flag of essential) {
    const key = flag.split('=')[0];
    if (!merged.some((f) => f === flag || f.startsWith(key + '='))) {
      merged.push(flag);
    }
  }
  return merged;
}

function getFreePort() {
  return new Promise((resolve, reject) => {
    const server = net.createServer();
    server.listen(0, '127.0.0.1', () => {
      const port = server.address().port;
      server.close(() => resolve(port));
    });
    server.on('error', reject);
  });
}

function waitForChrome(port, timeout = 30000) {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    function check() {
      const req = http.get(`http://127.0.0.1:${port}/json/version`, (res) => {
        let data = '';
        res.on('data', (chunk) => (data += chunk));
        res.on('end', () => {
          try {
            resolve(JSON.parse(data));
          } catch (_) {
            resolve({});
          }
        });
      });
      req.on('error', () => {
        if (Date.now() - start > timeout) {
          reject(
            new Error(
              `[puppeteer-termux] Timed out waiting for Chromium on port ${port}.\n` +
              'Make sure Chromium is installed: pkg install chromium'
            )
          );
        } else {
          setTimeout(check, 500);
        }
      });
      req.end();
    }
    check();
  });
}

/**
 * Launch Chromium wrapped with xvfb-run for headful mode on Termux.
 * Returns an object compatible with chrome-launcher's return value.
 */
export function launchWithXvfbRun(chromePath, chromeFlags) {
  return new Promise(async (resolve, reject) => {
    let port;
    try {
      port = await getFreePort();
    } catch (err) {
      return reject(new Error('[puppeteer-termux] Could not find a free port: ' + err.message));
    }

    const flags = [
      ...chromeFlags.filter((f) => !f.startsWith('--remote-debugging-port')),
      `--remote-debugging-port=${port}`,
    ];

    const proc = spawn('xvfb-run', ['--auto-servernum', chromePath, ...flags], {
      stdio: ['ignore', 'ignore', 'pipe'],
      detached: false,
    });

    // Drain stderr silently (avoid buffer stall)
    proc.stderr.on('data', () => {});

    // Spawn errors (e.g. xvfb-run not installed)
    proc.on('error', (err) => {
      reject(
        new Error(
          '[puppeteer-termux] Failed to start xvfb-run.\n' +
          'Install it in Termux with: pkg install xorg-server-xvfb\n' +
          err.message
        )
      );
    });

    // If the process exits before Chrome is ready, reject
    proc.once('exit', (code) => {
      if (code !== null && code !== 0) {
        reject(
          new Error(
            `[puppeteer-termux] xvfb-run / Chromium exited unexpectedly with code ${code}.\n` +
            'Check that Chromium is installed: pkg install chromium'
          )
        );
      }
    });

    waitForChrome(port)
      .then(() => {
        resolve({
          port,
          pid: proc.pid,
          process: proc,
          kill: () => {
            try { proc.kill('SIGKILL'); } catch (_) {}
          },
        });
      })
      .catch(reject);
  });
}
